find:
prevIn = sample;
prevMid = mid;
prevOut = out;

if (left == 0)
	return;

prevIn  = state[0];
prevMid = state[1];
prevOut = state[2];
energy  = state[3];

b0 = coeff[0];
b1 = coeff[1];
b2 = coeff[2];
b3 = coeff[3];

do {
	long double sample = *in++;
	long double mid = (sample - prevIn * b2) + prevMid * b0;
	long double out = (mid - prevMid * b3) + prevOut * b1;

	energy = energy + out * out;

	prevIn = sample;
	prevMid = mid;
	prevOut = out;
} while (--left != 0);

replace:
prevIn  = state[0];
prevMid = state[1];
prevOut = state[2];
energy  = state[3];

b0 = coeff[0];
b1 = coeff[1];
b2 = coeff[2];
b3 = coeff[3];

while (left-- != 0) {
	long double sample = *in++;
	long double mid = (sample - prevIn * b2) + prevMid * b0;
	long double out = (mid - prevMid * b3) + prevOut * b1;

	energy = energy + out * out;

	prevIn = sample;
	prevMid = mid;
	prevOut = out;
}
